def anchor(n):
    if "__pyx_" in n:
        m = CY.search(n)
        if m:
            pkg = m.group(2)[: int(m.group(1))]
            if pkg in CYPKG: return CYPKG[pkg]
            if pkg in ("_csparsetools",): return "scipy"
            if pkg in ("_arma_innovations", "_hamilton_filter", "_kim_smoother", "_initialization", "_representation", "_kalman_filter", "_kalman_smoother", "_simulation_smoother", "_tools", "_smoothers", "_filters", "_exponential_smoothers", "_innovations", "_stl", "_ets_smooth", "_cy_statespace"): return "statsmodels"
        return None  # cython runtime: take the neighbours'
    for b, r in ANCHORS:
        if r.search(n): return b
    return None

rows = [(int(sz), name) for sz, name in (l.rstrip("\n").split("\t") for l in open("names.tsv"))]
anch = [anchor(n) for _, n in rows]
# Fill gaps whose two neighbours agree.
owner = list(anch)
prev = None; i = 0
N = len(rows)
j = 0
while j < N:
    if anch[j] is not None:
        prev = anch[j]; j += 1; continue
    k = j
    while k < N and anch[k] is None: k += 1
    nxt = anch[k] if k < N else None
    fill = prev if (prev == nxt) else "mixed or unattributed"
    for t in range(j, k): owner[t] = fill
    j = k
tot = Counter(); n = Counter(); direct = Counter()
for (sz, name), o, a in zip(rows, owner, anch):
    tot[o] += sz; n[o] += 1
    if a: direct[o] += sz
total = sum(tot.values())
print(f"code bodies: {N} functions, {total:,} bytes; anchored directly: {sum(direct.values()):,} ({100*sum(direct.values())/total:.0f}%)")
for b, sz in tot.most_common():
    print(f"  {b:26s} {sz:>12,} B  {100*sz/total:5.1f}%  fns={n[b]:>6}  anchored={direct[b]:>12,}")
# Spot-check the largest mixed regions.
print("\nlargest functions in 'mixed or unattributed':")
mixed = sorted(((sz, nm) for (sz, nm), o in zip(rows, owner) if o == "mixed or unattributed"), reverse=True)[:25]
for sz, nm in mixed: print(f"  {sz:>9,}  {nm[:100]}")
# Spot-check: twenty random anchored-by-neighbour attributions.
import random
random.seed(3)
filled = [(nm, o) for (sz, nm), o, a in zip(rows, owner, anch) if a is None and o != "mixed or unattributed"]
print("\nsample of neighbour-filled attributions:")
for nm, o in random.sample(filled, 25): print(f"  {o:14s} <- {nm[:80]}")
